import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { prisma } from "@/lib/prisma";
import { getSession } from "@/lib/auth";

/**
 * GET /api/admin/users
 * ดึงรายชื่อผู้ใช้งานทั้งหมด (สำหรับ Admin)
 * Query params: ?search=...&role=...
 */
export async function GET(request: Request) {
  try {
    const session = await getSession(request as NextRequest);

    // ตรวจสอบสิทธิ์ว่าต้องเป็น ADMIN เท่านั้น
    if (!session || session.role !== "ADMIN") {
      return NextResponse.json(
        { error: "ไม่มีสิทธิ์เข้าถึง (สำหรับผู้ดูแลระบบเท่านั้น)" },
        { status: 403 }
      );
    }

    const { searchParams } = new URL(request.url);
    const search = searchParams.get("search");
    const role = searchParams.get("role");

    const where: any = {};

    if (role) {
      where.role = role.toUpperCase();
    }

    if (search) {
      where.OR = [
        { email: { contains: search, mode: "insensitive" } },
        { studentId: { contains: search, mode: "insensitive" } },
        {
          profile: {
            OR: [
              { firstName: { contains: search, mode: "insensitive" } },
              { lastName: { contains: search, mode: "insensitive" } },
            ],
          },
        },
      ];
    }

    const users = await prisma.user.findMany({
      where,
      select: {
        id: true,
        studentId: true,
        email: true,
        role: true,
        createdAt: true,
        profile: {
          select: {
            firstName: true,
            lastName: true,
            faculty: true,
            major: true,
          }
        }
      },
      orderBy: { createdAt: "desc" },
    });

    return NextResponse.json({ users });
  } catch (error) {
    console.error("[GET /api/admin/users]", error);
    return NextResponse.json(
      { error: "เกิดข้อผิดพลาดในการดึงข้อมูลผู้ใช้งาน" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { signToken } from "@/lib/auth";

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { role } = body;

    // Convert dev roles to JWT roles
    let jwtRole = "ATHLETE";
    if (role === "club") jwtRole = "CLUB";
    if (role === "staff") jwtRole = "STAFF";
    if (role === "admin") jwtRole = "ADMIN";
    if (role === "superadmin") jwtRole = "SUPERADMIN";

    const token = signToken({
      id: "dev-user-id",
      role: jwtRole as any,
      studentId: "66000000", // fake student id
      clubId: role === "club" ? "clm2xt6j50000aabc12345678" : undefined,
    });

    const response = NextResponse.json({ message: "Dev Login Success" });

    response.cookies.set("token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "strict",
      path: "/",
      maxAge: 24 * 60 * 60,
    });

    response.cookies.set("role", role, {
      httpOnly: false,
      secure: process.env.NODE_ENV === "production",
      sameSite: "strict",
      path: "/",
      maxAge: 24 * 60 * 60,
    });

    return response;
  } catch (error) {
    return NextResponse.json({ error: "Failed to dev login" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { NextRequest } from "next/server";
import { prisma } from "@/lib/prisma";
import { getSession } from "@/lib/auth";

/**
 * GET /api/competitions
 * ดูรายการแข่งขันทั้งหมด
 * Query: ?status=...
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status");

    const where: Record<string, unknown> = {};

    if (status) where.status = status.toUpperCase();

    const competitions = await prisma.competition.findMany({
      where,
      include: {
        quotas: true,
        _count: {
          select: { applications: true },
        },
      },
      orderBy: { createdAt: "desc" },
    });

    return NextResponse.json({ competitions });
  } catch (error) {
    console.error("[GET /api/competitions]", error);
    return NextResponse.json(
      { error: "เกิดข้อผิดพลาดภายในระบบ" },
      { status: 500 }
    );
  }
}

/**
 * POST /api/competitions
 * เจ้าหน้าที่/Admin สร้างโปรแกรมการแข่งขันประจำปี
 *
 * Body: { name, round, year, deadline, quotas: [{ sport, maxStarters, maxSubstitutes, ageLimit }] }
 * Returns: competition object
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getSession(request);

    if (!session || (session.role !== "STAFF" && session.role !== "ADMIN" && session.role !== "SUPERADMIN")) {
      return NextResponse.json(
        { error: "เฉพาะเจ้าหน้าที่หรือผู้ดูแลระบบเท่านั้นที่สามารถสร้างโปรแกรมการแข่งขันได้" },
        { status: 403 }
      );
    }

    const body = await request.json();
    const { name, round, year, deadline, quotas } = body;

    if (!name || !round || !year) {
      return NextResponse.json(
        { error: "กรุณากรอกข้อมูลให้ครบถ้วน (name, round, year)" },
        { status: 400 }
      );
    }

    const competition = await prisma.competition.create({
      data: {
        name,
        round,
        year: parseInt(year),
        deadline: deadline ? new Date(deadline) : null,
        status: "OPEN",
        quotas: quotas && quotas.length > 0 ? {
          create: quotas.map((q: any) => ({
            sport: q.sport,
            maxStarters: parseInt(q.maxStarters || "0"),
            maxSubstitutes: parseInt(q.maxSubstitutes || "0"),
            ageLimit: q.ageLimit ? parseInt(q.ageLimit) : null
          }))
        } : undefined
      },
      include: {
        quotas: true,
      },
    });

    return NextResponse.json(
      { message: "สร้างรายการแข่งขันสำเร็จ", competition },
      { status: 201 }
    );
  } catch (error) {
    console.error("[POST /api/competitions]", error);
    return NextResponse.json(
      { error: "เกิดข้อผิดพลาดภายในระบบ" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { prisma } from "@/lib/prisma";
import bcrypt from "bcryptjs";
import { requireAuth } from "@/lib/auth";

export async function POST(request: Request) {
  try {
    const auth = await requireAuth(request as NextRequest, "STAFF", "ADMIN", "SUPERADMIN");
    if ("error" in auth) return auth.error;

    const data = await request.json();

    if (!Array.isArray(data.students) || data.students.length === 0) {
      return NextResponse.json({ error: "Invalid data format or empty list" }, { status: 400 });
    }

    let successCount = 0;
    let errorCount = 0;
    const errors: string[] = [];

    for (const student of data.students) {
      const studentId = String(student.studentId || "").trim();
      if (!studentId) {
        errorCount++;
        errors.push("Missing studentId");
        continue;
      }

      const firstName = student.firstName?.trim() || "-";
      const lastName = student.lastName?.trim() || "-";
      const faculty = student.faculty?.trim() || "-";
      const major = student.major?.trim() || "-";
      const email = `${studentId}@up.ac.th`;

      const year = String(student.year || "1");
      const nationalId = String(student.nationalId || "-");
      const nationality = String(student.nationality || "ไทย");
      const birthDate = student.birthDate ? new Date(student.birthDate) : new Date("2000-01-01");
      const studentLevel = student.studentLevel === "GRADUATE" ? "GRADUATE" : "BACHELOR";
      const gpaSemester = student.gpaSemester ? String(student.gpaSemester) : null;
      const gpaCumulative = student.gpaCumulative ? String(student.gpaCumulative) : null;

      // History fields
      const hasParticipated = Boolean(student.hasParticipated);
      const firstSport = student.firstSport ? String(student.firstSport) : null;
      const participateCountBachelor = student.participateCountBachelor ? Number(student.participateCountBachelor) : null;
      const participateCountMaster = student.participateCountMaster ? Number(student.participateCountMaster) : null;
      const participateCountPhd = student.participateCountPhd ? Number(student.participateCountPhd) : null;
      const lastParticipateYear = student.lastParticipateYear ? String(student.lastParticipateYear) : null;
      const isNationalTeam = Boolean(student.isNationalTeam);
      const pastCompetitions = student.pastCompetitions || null;

      try {
        // Check if user already exists
        const existingUser = await prisma.user.findUnique({
          where: { studentId },
        });

        if (existingUser) {
          // Update profile if exists
          await prisma.athleteProfile.upsert({
            where: { userId: existingUser.id },
            update: {
              firstName,
              lastName,
              faculty,
              major,
              year,
              nationalId,
              nationality,
              birthDate,
              studentLevel,
              gpaSemester,
              gpaCumulative,
              hasParticipated,
              firstSport,
              participateCountBachelor,
              participateCountMaster,
              participateCountPhd,
              lastParticipateYear,
              isNationalTeam,
              pastCompetitions,
            },
            create: {
              userId: existingUser.id,
              firstName,
              lastName,
              faculty,
              major,
              year,
              nationalId,
              nationality,
              birthDate,
              studentLevel,
              gpaSemester,
              gpaCumulative,
              hasParticipated,
              firstSport,
              participateCountBachelor,
              participateCountMaster,
              participateCountPhd,
              lastParticipateYear,
              isNationalTeam,
              pastCompetitions,
              addressNo: "-",
              subDistrict: "-",
              district: "-",
              province: "-",
              postalCode: "-",
              phone: "-",
            },
          });
          successCount++;
        } else {
          // Create new user & profile
          const hashedPassword = await bcrypt.hash(studentId, 10);

          await prisma.$transaction(async (tx) => {
            const newUser = await tx.user.create({
              data: {
                studentId,
                email,
                password: hashedPassword,
                role: "ATHLETE",
              },
            });

            await tx.athleteProfile.create({
              data: {
                userId: newUser.id,
                firstName,
                lastName,
                faculty,
                major,
                year,
                nationalId,
                nationality,
                birthDate,
                studentLevel,
                gpaSemester,
                gpaCumulative,
                hasParticipated,
                firstSport,
                participateCountBachelor,
                participateCountMaster,
                participateCountPhd,
                lastParticipateYear,
                isNationalTeam,
                pastCompetitions,
                addressNo: "-",
                subDistrict: "-",
                district: "-",
                province: "-",
                postalCode: "-",
                phone: "-",
              },
            });
          });
          successCount++;
        }
      } catch (err: any) {
        console.error(`Error importing student ${studentId}:`, err);
        errorCount++;
        errors.push(`Failed for ${studentId}: ${err.message}`);
      }
    }

    return NextResponse.json({
      success: true,
      successCount,
      errorCount,
      errors,
    });
  } catch (error: any) {
    console.error("Import Error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { prisma } from "@/lib/prisma";
import { requireAuth } from "@/lib/auth";

export async function GET(request: Request) {
  try {
    const auth = await requireAuth(request as NextRequest, "STAFF", "ADMIN", "SUPERADMIN");
    if ("error" in auth) return auth.error;

    const sports = await prisma.sportConfig.findMany({
      orderBy: { createdAt: "asc" }
    });

    let scheduleSetting = await prisma.systemSetting.findUnique({
      where: { key: "QUALIFIER_SCHEDULE" }
    });

    // Default schedule if not exists
    if (!scheduleSetting) {
      const defaultSchedule = {
        region: "ภาคเหนือ",
        hostUniversity: "มหาวิทยาลัยราชภัฏนครสวรรค์",
        startDate: "2026-10-24",
        endDate: "2026-10-29",
        location: "มหาวิทยาลัยราชภัฏนครสวรรค์",
        note: "กีฬามหาวิทยาลัยแห่งประเทศไทย ครั้งที่ 52 รอบคัดเลือกเขตภาคเหนือ"
      };
      scheduleSetting = await prisma.systemSetting.create({
        data: {
          key: "QUALIFIER_SCHEDULE",
          value: defaultSchedule as any
        }
      });
    }

    return NextResponse.json({
      sports,
      schedule: scheduleSetting.value
    });
  } catch (error) {
    console.error("[GET /api/staff/settings]", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const auth = await requireAuth(request as NextRequest, "STAFF", "ADMIN", "SUPERADMIN");
    if ("error" in auth) return auth.error;

    const body = await request.json();
    const { sports, schedule } = body;


    // Save sports
    if (sports && Array.isArray(sports)) {
      // Very naive approach: Delete all and recreate to sync 
      // (in a real prod app, you might want to upsert or sync individually)
      await prisma.sportConfig.deleteMany({});
      await prisma.sportConfig.createMany({
        data: sports.map((s: any) => ({
          name: s.name,
          category: s.category,
          maxAthletes: s.maxAthletes,
          isOpen: s.isOpen,
          positions: s.positions || [],
          requirements: s.requirements || "",
          competitionType: s.competitionType || "",
          qualifierNote: s.qualifierNote || "",
          reachedTop16LastYear: s.reachedTop16LastYear,
          top16Note: s.top16Note || ""
        }))
      });
    }

    // Save schedule
    if (schedule) {
      await prisma.systemSetting.upsert({
        where: { key: "QUALIFIER_SCHEDULE" },
        update: { value: schedule },
        create: { key: "QUALIFIER_SCHEDULE", value: schedule }
      });
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("[POST /api/staff/settings]", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import LogoutButton from "@/components/shared/LogoutButton";

type Activity = {
  id: string;
  title: string;
  date: string;
  location: string;
  description: string;
  participants: number;
  documents: string[];
  images: string[];
  status: "pending" | "approved" | "rejected";
  rejectedReason?: string;
};

const STATUS_LABEL = {
  pending: { label: "รอการตรวจสอบ", className: "bg-slate-100 text-slate-700 border-slate-200" },
  approved: { label: "อนุมัติแล้ว", className: "bg-emerald-50 text-emerald-800 border-emerald-200" },
  rejected: { label: "ไม่ผ่านเกณฑ์", className: "bg-rose-50 text-rose-800 border-rose-200" },
};

export default function ClubActivitiesPage() {
  const router = useRouter();
  const [activities, setActivities] = useState<Activity[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/activities")
      .then(res => res.json())
      .then(data => {
        if (data.activities) {
          const mapped = data.activities.map((a: any) => ({
            ...a,
            date: new Date(a.date).toLocaleDateString("th-TH", { year: "numeric", month: "short", day: "numeric" }),
            participants: 0,
            documents: [],
            images: []
          }));
          setActivities(mapped);
        }
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  }, []);

  const approvedCount = activities.filter((a) => a.status === "approved").length;
  const canSubmit = approvedCount >= 2;

  return (
    <div className="min-h-screen bg-slate-50 py-10 px-4 text-slate-800 font-sans">
      <div className="max-w-7xl mx-auto space-y-6">

        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-200 pb-4">
          <div>
            <span className="text-xs uppercase tracking-wider font-semibold text-slate-500">
              ระบบสารสนเทศชมรมกีฬา · กองกิจการนิสิต มหาวิทยาลัยพะเยา
            </span>
            <h1 className="text-xl font-bold text-slate-900 mt-0.5">
              การรายงานผลการดำเนินกิจกรรมของชมรมกีฬา
            </h1>
            <p className="text-xs text-slate-500">
              กิจกรรมที่ผ่านการอนุมัติแล้ว {approvedCount} กิจกรรม
              {!canSubmit && (
                <span className="text-slate-600 font-medium ml-2">(เกณฑ์ขั้นต่ำ: ต้องมีกิจกรรมที่ผ่านการอนุมัติอย่างน้อย 2 กิจกรรม)</span>
              )}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => router.push("/club/activities/new")}
              className="bg-blue-900 hover:bg-blue-800 text-white text-xs font-medium px-4 py-2 rounded-lg transition-colors cursor-pointer"
            >
              + บันทึกกิจกรรมใหม่
            </button>
            <button
              onClick={() => router.back()}
              className="border border-slate-300 hover:bg-slate-50 text-slate-700 text-xs font-medium px-3.5 py-2 rounded-lg transition-colors"
            >
              ย้อนกลับ
            </button>
            <LogoutButton />
          </div>
        </div>

        {/* Progress */}
        <div className="bg-white rounded-xl border border-slate-200 p-4 shadow-xs">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-medium text-slate-600">ความพร้อมตามเกณฑ์กิจกรรมชมรม</span>
            <span className="text-xs font-bold text-slate-900">{approvedCount} / 2 กิจกรรม</span>
          </div>
          <div className="w-full bg-slate-100 rounded-full h-2 overflow-hidden">
            <div
              className={`h-2 rounded-full transition-all ${approvedCount >= 2 ? "bg-emerald-800" : "bg-blue-900"}`}
              style={{ width: `${Math.min((approvedCount / 2) * 100, 100)}%` }}
            />
          </div>
          {canSubmit && (
            <p className="text-emerald-800 text-xs mt-2 font-medium">✓ ครบเกณฑ์แล้ว สามารถส่งใบสมัครนักกีฬาได้</p>
          )}
        </div>

        {/* Activity Cards */}
        <div className="space-y-4">
          {loading ? (
            <div className="text-center py-12 text-slate-400 text-sm">กำลังโหลดข้อมูล...</div>
          ) : activities.length === 0 ? (
            <div className="bg-white rounded-xl border border-slate-200 p-8 text-center text-slate-400 text-xs shadow-xs">
              ยังไม่มีรายงานกิจกรรม กด + บันทึกกิจกรรมใหม่ เพื่อเริ่มต้น
            </div>
          ) : (
            activities.map((a) => {
              const statusCfg = STATUS_LABEL[a.status] || STATUS_LABEL["pending"];
              return (
                <div key={a.id} className="bg-white rounded-xl border border-slate-200 shadow-xs p-5 space-y-2">
                  <div className="flex items-start justify-between gap-4">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <h2 className="font-semibold text-slate-900 text-sm">{a.title}</h2>
                        <span className={`text-[10px] px-2 py-0.5 rounded border font-medium ${statusCfg.className}`}>
                          {statusCfg.label}
                        </span>
                      </div>
                      <p className="text-xs text-slate-500">{a.date} · {a.location}</p>
                    </div>
                  </div>

                  <p className="text-xs text-slate-600 leading-relaxed">{a.description}</p>

                  <div className="flex flex-wrap gap-4 text-xs text-slate-500 pt-2 border-t border-slate-100">
                    <span>ผู้เข้าร่วม {a.participants} คน</span>
                    <span>เอกสารประกอบ {a.documents.length} ฉบับ</span>
                    <span>ภาพถ่าย {a.images.length} ภาพ</span>
                  </div>

                  {a.status === "rejected" && a.rejectedReason && (
                    <div className="p-2.5 bg-rose-50 border border-rose-200 rounded-lg text-xs text-rose-800">
                      <strong>เหตุผลที่ไม่อนุมัติ:</strong> {a.rejectedReason}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>

        {/* Submit Button */}
        {canSubmit && (
          <div className="mt-6">
            <button
              onClick={() => router.push("/club/athletes")}
              className="w-full bg-blue-900 hover:bg-blue-800 text-white font-medium py-3 rounded-xl text-xs transition-colors cursor-pointer"
            >
              ครบตามเกณฑ์กิจกรรมแล้ว — ดำเนินการคัดเลือกและจัดทำบัญชีรายชื่อนักกีฬา
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import LogoutButton from "@/components/shared/LogoutButton";

type SpecialRequest = {
  id: string;
  title: string;
  reason: string;
  date: string;
  document: string;
  status: "pending" | "approved" | "rejected";
  rejectedReason?: string;
};

const STATUS_LABEL: Record<string, { label: string; className: string }> = {
  PENDING: { label: "รอการพิจารณา", className: "bg-slate-100 text-slate-700 border-slate-200" },
  APPROVED: { label: "อนุมัติแล้ว", className: "bg-emerald-50 text-emerald-800 border-emerald-200" },
  REJECTED: { label: "ไม่อนุมัติ", className: "bg-rose-50 text-rose-800 border-rose-200" },
  pending: { label: "รอการพิจารณา", className: "bg-slate-100 text-slate-700 border-slate-200" },
  approved: { label: "อนุมัติแล้ว", className: "bg-emerald-50 text-emerald-800 border-emerald-200" },
  rejected: { label: "ไม่อนุมัติ", className: "bg-rose-50 text-rose-800 border-rose-200" },
};

export default function ClubRequestsPage() {
  const router = useRouter();
  const [requests, setRequests] = useState<SpecialRequest[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/clubs/requests")
      .then(res => res.json())
      .then(data => {
        if (data.requests) {
          const mapped = data.requests.map((r: any) => ({
            ...r,
            date: new Date(r.createdAt).toLocaleDateString("th-TH"),
            document: r.documentUrl || "ดูเอกสารแนบ"
          }));
          setRequests(mapped);
        }
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  }, []);

  return (
    <div className="min-h-screen bg-slate-50 py-10 px-4 text-slate-800 font-sans">
      <div className="max-w-6xl mx-auto space-y-6">

        {/* Top Header */}
        <div className="flex items-center justify-between border-b border-slate-200 pb-4">
          <div>
            <span className="text-xs uppercase tracking-wider font-semibold text-slate-500">
              ระบบสารสนเทศชมรมกีฬา · กองกิจการนิสิต มหาวิทยาลัยพะเยา
            </span>
            <h1 className="text-xl font-bold text-slate-900 mt-0.5">
              การยื่นและติดตามคำร้องขออนุมัติกรณีพิเศษ
            </h1>
            <p className="text-xs text-slate-500">
              ยื่นคำร้องผ่านอาจารย์ที่ปรึกษาชมรมเพื่อเสนอต่อคณะกรรมการกองกิจการนิสิต
            </p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => router.push("/club/requests/new")}
              className="bg-blue-900 hover:bg-blue-800 text-white text-xs font-medium px-4 py-2 rounded-lg transition-colors cursor-pointer"
            >
              + ยื่นคำร้องขออนุมัติใหม่
            </button>
            <button
              onClick={() => router.back()}
              className="border border-slate-300 hover:bg-slate-50 text-slate-700 text-xs font-medium px-3.5 py-2 rounded-lg transition-colors cursor-pointer"
            >
              ย้อนกลับ
            </button>
            <LogoutButton />
          </div>
        </div>

        {/* Informational Guidance Box */}
        <div className="bg-white border border-slate-200 rounded-xl p-4 text-xs text-slate-600 shadow-xs leading-relaxed">
          <strong>แนวปฏิบัติการยื่นคำร้อง:</strong> สำหรับกรณีนักกีฬาที่มีคุณสมบัติไม่ครบถ้วนตามเกณฑ์ปกติ หรือมีความจำเป็นเร่งด่วนในการเปลี่ยนตัวนักกีฬา
          ชมรมจะต้องแนบหนังสือรับรองความเห็นชอบจากอาจารย์ที่ปรึกษาชมรมกีฬาเพื่อประกอบการพิจารณาของกองกิจการนิสิต
        </div>

        {/* Requests List */}
        <div className="space-y-3">
          {loading ? (
            <div className="text-center py-12 text-slate-400">กำลังโหลด...</div>
          ) : requests.length === 0 ? (
            <div className="bg-white rounded-xl border border-slate-200 p-8 text-center text-slate-400 text-xs shadow-xs">
              ยังไม่มีประวัติการยื่นคำร้องกรณีพิเศษ
            </div>
          ) : (
            requests.map((r) => (
              <div key={r.id} className="bg-white rounded-xl border border-slate-200 p-5 shadow-xs space-y-3">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <h2 className="font-semibold text-slate-900 text-sm">{r.title}</h2>
                      <span className={`text-[10px] px-2 py-0.5 rounded border font-medium ${STATUS_LABEL[r.status]?.className || STATUS_LABEL["pending"].className}`}>
                        {STATUS_LABEL[r.status]?.label || "รอพิจารณา"}
                      </span>
                    </div>
                    <p className="text-xs text-slate-500 leading-relaxed">{r.reason}</p>
                  </div>
                  <span className="text-[11px] text-slate-400 shrink-0 font-medium">ยื่นเมื่อ: {r.date}</span>
                </div>

                <div className="pt-3 border-t border-slate-100 flex items-center justify-between text-xs text-slate-500">
                  <span>เอกสารประกอบ: <strong className="text-blue-900">{r.document}</strong></span>
                  <button
                    onClick={() => alert(`เปิดดูเอกสาร ${r.document}`)}
                    className="text-blue-900 hover:underline font-medium cursor-pointer"
                  >
                    เปิดดูเอกสารแนบ →
                  </button>
                </div>

                {r.status === "rejected" && r.rejectedReason && (
                  <div className="p-3 bg-rose-50 border border-rose-200 rounded-lg text-xs text-rose-800">
                    <strong>เหตุผลที่ไม่อนุมัติ:</strong> {r.rejectedReason}
                  </div>
                )}
              </div>
            ))
          )}
        </div>

      </div>
    </div>
  );
}

