"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import LogoutButton from "@/components/shared/LogoutButton";
import Link from "next/link";

type Coach = {
  id: string;
  name: string;
  phone: string | null;
};

type TrainingReport = {
  id: string;
  date: string;
  progress: string;
  issues: string | null;
  photoUrl: string | null;
};

type TrainingProgram = {
  id: string;
  goal: string;
  schedule: string | null;
  reports: TrainingReport[];
};

export default function ClubTrainingPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [coaches, setCoaches] = useState<Coach[]>([]);
  const [programs, setPrograms] = useState<TrainingProgram[]>([]);

  // Forms
  const [coachForm, setCoachForm] = useState({ name: "", phone: "" });
  const [programForm, setProgramForm] = useState({ goal: "", schedule: "" });
  const [reportForm, setReportForm] = useState({ programId: "", date: "", progress: "", issues: "", photoUrl: "" });

  const fetchData = async () => {
    try {
      const res = await fetch("/api/club/training");
      const data = await res.json();
      setCoaches(data.coaches ?? []);
      setPrograms(data.programs ?? []);
    } catch {
      console.error("Fetch failed");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleAddCoach = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!coachForm.name) return;
    const res = await fetch("/api/club/training", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "ADD_COACH", ...coachForm })
    });
    if (res.ok) {
      setCoachForm({ name: "", phone: "" });
      fetchData();
    }
  };

  const handleCreateProgram = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!programForm.goal) return;
    const res = await fetch("/api/club/training", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "CREATE_PROGRAM", ...programForm })
    });
    if (res.ok) {
      setProgramForm({ goal: "", schedule: "" });
      fetchData();
    }
  };

  const handleAddReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reportForm.programId || !reportForm.progress || !reportForm.date) return;
    const res = await fetch("/api/club/training", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "ADD_REPORT", ...reportForm })
    });
    if (res.ok) {
      setReportForm({ programId: "", date: "", progress: "", issues: "", photoUrl: "" });
      fetchData();
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row text-slate-800 font-sans">
      {/* Sidebar */}
      <aside className="w-full md:w-64 bg-slate-900 text-slate-300 flex flex-col">
        <div className="p-6 border-b border-slate-800">
          <span className="text-[10px] font-bold tracking-widest uppercase text-slate-500 mb-1 block">
            Club Management
          </span>
          <h2 className="text-lg font-bold text-white leading-tight">ประธานชมรม</h2>
        </div>
        <nav className="flex-1 py-4 px-3 space-y-1">
          <Link href="/club/athletes" className="block px-3 py-2 rounded-lg text-sm font-medium hover:bg-slate-800 hover:text-white transition-colors">รายชื่อผู้สมัคร (Phase A)</Link>
          <Link href="/club/training" className="block px-3 py-2 rounded-lg text-sm font-medium bg-blue-600 text-white transition-colors">จัดการการฝึกซ้อม (Phase B)</Link>
          <Link href="/club/review" className="block px-3 py-2 rounded-lg text-sm font-medium hover:bg-slate-800 hover:text-white transition-colors">คัดเลือกนักกีฬา (Phase C)</Link>
        </nav>
        <div className="p-4 border-t border-slate-800">
          <LogoutButton />
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="max-w-5xl mx-auto space-y-8">
          <div>
            <h1 className="text-2xl font-bold text-slate-900">Phase B: จัดการการฝึกซ้อม</h1>
            <p className="text-sm text-slate-500 mt-1">ผู้ฝึกสอน, โปรแกรมการฝึกซ้อม, และรายงานความก้าวหน้า</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Coaches Section */}
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <h2 className="text-lg font-bold mb-4">ผู้ฝึกสอน (Coaches)</h2>
              <form onSubmit={handleAddCoach} className="flex gap-2 mb-4">
                <input required placeholder="ชื่อ-สกุล" className="flex-1 border rounded-lg px-3 py-1.5 text-sm" value={coachForm.name} onChange={e => setCoachForm({...coachForm, name: e.target.value})} />
                <input placeholder="เบอร์โทรศัพท์" className="flex-1 border rounded-lg px-3 py-1.5 text-sm" value={coachForm.phone} onChange={e => setCoachForm({...coachForm, phone: e.target.value})} />
                <button type="submit" className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-sm font-medium hover:bg-slate-800">เพิ่ม</button>
              </form>
              <div className="space-y-2">
                {coaches.map(c => (
                  <div key={c.id} className="bg-slate-50 p-3 rounded-lg border text-sm flex justify-between">
                    <span className="font-semibold">{c.name}</span>
                    <span className="text-slate-500">{c.phone || "-"}</span>
                  </div>
                ))}
                {coaches.length === 0 && <p className="text-xs text-slate-400">ยังไม่มีผู้ฝึกสอน</p>}
              </div>
            </div>

            {/* Program Section */}
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <h2 className="text-lg font-bold mb-4">โปรแกรมการฝึกซ้อมประจำวัน/สัปดาห์</h2>
              <form onSubmit={handleCreateProgram} className="flex flex-col gap-2 mb-4">
                <input required placeholder="เป้าหมาย (เช่น เน้นพละกำลังและแท็คติก)" className="w-full border rounded-lg px-3 py-1.5 text-sm" value={programForm.goal} onChange={e => setProgramForm({...programForm, goal: e.target.value})} />
                <textarea placeholder="ตารางการฝึก (เช่น จ-ศ 17:00-19:00 วิ่ง 5km)" className="w-full border rounded-lg px-3 py-1.5 text-sm" value={programForm.schedule} onChange={e => setProgramForm({...programForm, schedule: e.target.value})} />
                <button type="submit" className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-sm font-medium hover:bg-slate-800 w-full">สร้างโปรแกรมการฝึก</button>
              </form>
            </div>
          </div>

          {/* Reports Section */}
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
            <h2 className="text-lg font-bold mb-4">รายงานความก้าวหน้าการฝึกซ้อม</h2>
            {programs.length === 0 ? (
              <p className="text-sm text-slate-500">กรุณาสร้างโปรแกรมการฝึกก่อนรายงานผล</p>
            ) : (
              <form onSubmit={handleAddReport} className="grid grid-cols-1 md:grid-cols-4 gap-3 mb-6 bg-slate-50 p-4 rounded-lg border">
                <select required className="col-span-1 md:col-span-4 border rounded-lg px-3 py-1.5 text-sm" value={reportForm.programId} onChange={e => setReportForm({...reportForm, programId: e.target.value})}>
                  <option value="">เลือกโปรแกรมที่ต้องการรายงาน...</option>
                  {programs.map(p => <option key={p.id} value={p.id}>{p.goal}</option>)}
                </select>
                <input required type="date" className="border rounded-lg px-3 py-1.5 text-sm" value={reportForm.date} onChange={e => setReportForm({...reportForm, date: e.target.value})} />
                <input required placeholder="ผลความก้าวหน้า" className="border rounded-lg px-3 py-1.5 text-sm col-span-2" value={reportForm.progress} onChange={e => setReportForm({...reportForm, progress: e.target.value})} />
                <button type="submit" className="bg-blue-600 text-white px-3 py-1.5 rounded-lg text-sm font-medium hover:bg-blue-700">บันทึกรายงาน</button>
              </form>
            )}

            <div className="space-y-4">
              {programs.map(p => (
                <div key={p.id} className="border-t pt-4">
                  <h3 className="font-semibold text-slate-800 text-sm mb-2">โปรแกรม: {p.goal}</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    {p.reports.map(r => (
                      <div key={r.id} className="border rounded-lg p-3 text-sm bg-white shadow-xs">
                        <div className="flex justify-between font-semibold mb-1">
                          <span>{new Date(r.date).toLocaleDateString("th-TH")}</span>
                        </div>
                        <p className="text-slate-600 mt-1">ความก้าวหน้า: {r.progress}</p>
                      </div>
                    ))}
                    {p.reports.length === 0 && <p className="text-xs text-slate-400">ยังไม่มีรายงานสำหรับโปรแกรมนี้</p>}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useParams, useRouter } from "next/navigation";
import { useState, useEffect } from "react";

const STATUS_LABEL: Record<string, { label: string; className: string }> = {
  planned: { label: "รอตรวจสอบ", className: "bg-yellow-100 text-yellow-800" },
  approved: { label: "อนุมัติแล้ว", className: "bg-emerald-100 text-emerald-800" },
  rejected: { label: "ไม่ผ่าน", className: "bg-rose-100 text-rose-800" },
};

export default function StaffActivityDetailPage() {
  const router = useRouter();
  const params = useParams();
  const id = params.id as string;
  const [activity, setActivity] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [rejectReason, setRejectReason] = useState("");
  const [showRejectInput, setShowRejectInput] = useState(false);

  useEffect(() => {
    fetch(`/api/activities/${id}`)
      .then(res => res.json())
      .then(data => {
        if (data.activity) {
          setActivity({
            ...data.activity,
            clubName: data.activity.club?.name || "ไม่ทราบชื่อชมรม",
            submittedBy: "ประธานชมรม " + (data.activity.club?.name || ""),
            submittedAt: new Date(data.activity.createdAt).toLocaleDateString("th-TH"),
            date: new Date(data.activity.date).toLocaleDateString("th-TH"),
            participants: 0,
            documents: [],
            images: [],
            note: ""
          });
        }
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  }, [id]);

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center font-sans">
        <p className="text-slate-500">กำลังโหลด...</p>
      </div>
    );
  }

  if (!activity) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center font-sans">
        <p className="text-slate-500">ไม่พบข้อมูลกิจกรรม</p>
      </div>
    );
  }

  const handleApprove = async () => {
    setActionLoading(true);
    try {
      const res = await fetch(`/api/activities/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "approved" })
      });
      if (res.ok) {
        setActivity((prev: any) => ({ ...prev, status: "approved" }));
      }
    } catch (err) {
      console.error(err);
    } finally {
      setActionLoading(false);
    }
  };

  const handleReject = async () => {
    if (!rejectReason) return;
    setActionLoading(true);
    try {
      const res = await fetch(`/api/activities/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "rejected", rejectionReason: rejectReason })
      });
      if (res.ok) {
        setActivity((prev: any) => ({ ...prev, status: "rejected", rejectionReason: rejectReason }));
        setShowRejectInput(false);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setActionLoading(false);
    }
  };

  const s = STATUS_LABEL[activity.status] || { label: activity.status, className: "bg-slate-100 text-slate-600" };

  return (
    <div className="min-h-screen bg-slate-50 py-8 px-4 font-sans text-slate-800">
      <div className="max-w-full lg:max-w-6xl mx-auto">

        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <button
            onClick={() => router.back()}
            className="text-sm text-slate-500 hover:text-slate-700 flex items-center gap-1 cursor-pointer"
          >
            ← ย้อนกลับ
          </button>
          <span className={`text-sm font-medium px-3 py-1 rounded-full ${s.className}`}>
            {s.label}
          </span>
        </div>

        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 space-y-6">

          {/* ชื่อกิจกรรม */}
          <div>
            <p className="text-xs text-slate-400 mb-1">{activity.clubName}</p>
            <h1 className="text-xl font-bold text-slate-900">{activity.title}</h1>
            <p className="text-sm text-slate-500 mt-1">ยื่นโดย {activity.submittedBy} · {activity.submittedAt}</p>
          </div>

          {/* ข้อมูลกิจกรรม */}
          <div className="border-t border-slate-100 pt-5">
            <h2 className="text-sm font-bold text-slate-900 uppercase tracking-wide mb-3">รายละเอียดกิจกรรม</h2>
            <div className="grid grid-cols-2 gap-x-8 gap-y-3 text-sm">
              <div>
                <span className="text-slate-500">วันที่จัดกิจกรรม</span>
                <p className="font-semibold text-slate-900 mt-0.5">{activity.date}</p>
              </div>
              <div>
                <span className="text-slate-500">จำนวนผู้เข้าร่วม</span>
                <p className="font-semibold text-slate-900 mt-0.5">{activity.participants} คน</p>
              </div>
              <div className="col-span-2">
                <span className="text-slate-500">สถานที่</span>
                <p className="font-semibold text-slate-900 mt-0.5">{activity.location || "-"}</p>
              </div>
              <div className="col-span-2">
                <span className="text-slate-500">รายละเอียด</span>
                <p className="font-semibold text-slate-900 mt-0.5">{activity.description || "-"}</p>
              </div>
              {activity.note && (
                <div className="col-span-2">
                  <span className="text-slate-500">หมายเหตุ</span>
                  <p className="font-semibold text-slate-900 mt-0.5">{activity.note}</p>
                </div>
              )}
            </div>
          </div>

          {/* เอกสารแนบ */}
          <div className="border-t border-slate-100 pt-5">
            <h2 className="text-sm font-bold text-slate-900 uppercase tracking-wide mb-3">เอกสารและรูปภาพ</h2>
            <div className="space-y-2">
              {activity.documents && activity.documents.length > 0 ? activity.documents.map((d: string, i: number) => (
                <div key={i} className="flex items-center gap-2 bg-slate-50 rounded-lg px-3 py-2 text-sm text-slate-700">
                  <span>📄</span>
                  <span>{d}</span>
                </div>
              )) : <div className="text-sm text-slate-400">ไม่มีเอกสารแนบ</div>}
              {activity.images && activity.images.length > 0 ? activity.images.map((img: string, i: number) => (
                <div key={i} className="flex items-center gap-2 bg-slate-50 rounded-lg px-3 py-2 text-sm text-slate-700">
                  <span>🖼️</span>
                  <span>{img}</span>
                </div>
              )) : null}
            </div>
          </div>

          {/* ปุ่มอนุมัติ/ไม่อนุมัติ */}
          {activity.status === "planned" && (
            <div className="border-t border-slate-100 pt-5">
              <h2 className="text-sm font-bold text-slate-900 mb-3">ผลการตรวจสอบ</h2>

              {showRejectInput && (
                <div className="mb-3">
                  <textarea
                    className="w-full px-3 py-2.5 rounded-lg border border-rose-200 text-sm focus:outline-none focus:ring-2 focus:ring-rose-400 resize-none"
                    rows={3}
                    placeholder="ระบุเหตุผลที่ไม่อนุมัติ..."
                    value={rejectReason}
                    onChange={(e) => setRejectReason(e.target.value)}
                  />
                </div>
              )}

              <div className="flex gap-3">
                {showRejectInput ? (
                  <>
                    <button
                      onClick={() => setShowRejectInput(false)}
                      className="flex-1 px-4 py-2.5 rounded-lg border border-slate-200 text-slate-600 text-sm hover:bg-slate-50 transition-colors cursor-pointer"
                    >
                      ยกเลิก
                    </button>
                    <button
                      onClick={handleReject}
                      disabled={!rejectReason || actionLoading}
                      className="flex-1 px-4 py-2.5 rounded-lg bg-rose-600 hover:bg-rose-700 disabled:bg-slate-300 text-white text-sm font-medium transition-colors cursor-pointer"
                    >
                      {actionLoading ? "กำลังบันทึก..." : "ยืนยันไม่อนุมัติ"}
                    </button>
                  </>
                ) : (
                  <>
                    <button
                      onClick={() => setShowRejectInput(true)}
                      className="flex-1 px-4 py-2.5 rounded-lg border border-rose-200 text-rose-600 text-sm hover:bg-rose-50 transition-colors cursor-pointer"
                    >
                      ไม่อนุมัติ
                    </button>
                    <button
                      onClick={handleApprove}
                      disabled={actionLoading}
                      className="flex-1 px-4 py-2.5 rounded-lg bg-emerald-600 hover:bg-emerald-700 disabled:bg-emerald-400 text-white text-sm font-medium transition-colors cursor-pointer"
                    >
                      {actionLoading ? "กำลังบันทึก..." : "อนุมัติกิจกรรม"}
                    </button>
                  </>
                )}
              </div>
            </div>
          )}

          {/* ผลอนุมัติแล้ว */}
          {activity.status === "approved" && (
            <div className="border-t border-slate-100 pt-5">
              <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-4 text-center">
                <p className="text-emerald-700 font-medium text-sm">✓ อนุมัติกิจกรรมนี้แล้ว</p>
              </div>
            </div>
          )}

          {activity.status === "rejected" && (
            <div className="border-t border-slate-100 pt-5">
              <div className="bg-rose-50 border border-rose-100 rounded-xl p-4 text-center">
                <p className="text-rose-700 font-medium text-sm">✕ ไม่อนุมัติกิจกรรมนี้</p>
                {activity.rejectionReason && <p className="text-rose-500 text-xs mt-1">เหตุผล: {activity.rejectionReason}</p>}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

